func (h dtogen) append26(out []byte, v ToolCall) []byte {
	count := 3
	out = dtogenCBOR.AppendMapHeader(out, uint64(count))
	out = dtogenCBOR.AppendText(out, "a")
	out = h.append27(out, v.Arguments)
	out = dtogenCBOR.AppendText(out, "i")
	out = h.append3(out, v.ProviderCallID)
	out = dtogenCBOR.AppendText(out, "n")
	out = h.append3(out, v.Name)
	return out
}
func (h dtogen) read26(r *dtogenCodec.Reader, d, cap int) (v ToolCall, err error) {
	defer func() {
		if err == nil && v.Validate() != nil {
			err = dtogenCodec.ErrInvalidData
		}
	}()
	count, err := r.Map(d, cap)
	if err != nil {
		return v, err
	}
	previous := ""
	var seen [3]bool
	for i := 0; i < count; i++ {
		key, err := r.String(d+1, int(^uint(0)>>1))
		if err != nil {
			return v, err
		}
		// Strict canonical key ordering also rejects duplicates before assignment can overwrite them.
		if i > 0 && (len(key) < len(previous) || (len(key) == len(previous) && key <= previous)) {
			return v, dtogenCodec.ErrInvalidData
		}
		previous = key
		switch key {
		case "a":
			seen[0] = true
			v.Arguments, err = h.read27(r, d+1, int(^uint(0)>>1))
			if err != nil {
				return v, dtogenFmt.Errorf("Arguments: %w", err)
			}
		case "i":
			seen[1] = true
			v.ProviderCallID, err = h.read3(r, d+1, int(^uint(0)>>1))
			if err != nil {
				return v, dtogenFmt.Errorf("ProviderCallID: %w", err)
			}
		case "n":
			seen[2] = true
			v.Name, err = h.read3(r, d+1, int(^uint(0)>>1))
			if err != nil {
				return v, dtogenFmt.Errorf("Name: %w", err)
			}
		default:
			return v, dtogenCodec.ErrInvalidData
		}
	}
	if !seen[0] {
		return v, dtogenCodec.ErrInvalidData
	}
	if !seen[1] {
		return v, dtogenCodec.ErrInvalidData
	}
	if !seen[2] {
		return v, dtogenCodec.ErrInvalidData
	}
	return v, nil
}

